  // MARK: - Streaming uploads

  private func patterned(_ size: Int) -> Data {
    Data((0..<size).map { UInt8(truncatingIfNeeded: $0 &* 31 &+ 7) })
  }

  /// Lets the sequence of an upload carry on once the server has seen the first part.
  private final class Gate: @unchecked Sendable {
    private let lock = NSLock()
    private var isOpen = false
    private var waiters: [CheckedContinuation<Void, Never>] = []

    func open() {
      let held: [CheckedContinuation<Void, Never>] = lock.withLock {
        isOpen = true
        let all = waiters
        waiters = []
        return all
      }
      for waiter in held { waiter.resume() }
    }

    func wait() async {
      await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
        let ready: Bool = lock.withLock {
          if !isOpen { waiters.append(continuation) }
          return isOpen
        }
        if ready { continuation.resume() }
      }
    }
  }

  /* A streamed upload of unknown length is sent chunked, as it is read, and arrives intact. */
  @Test func testBhvStreaming023AStreamedUploadOfUnknownLengthIsSentChunkedAndArrivesIntact()
    async throws
  {
    let payload = patterned(300_000)
    let gate = Gate()
    let seen = LockedValue<RawConnection.Upload?>(nil)
    let server = try RawServer { connection, _, head in
      seen.set(connection.readUpload(head: head, onFirst: { gate.open() }))
      connection.reply(200)
    }
    defer { server.stop() }
    /* The second half is not offered until the server has the first, so a
     * client that buffered the body before sending would wait here for good. */
    let source = BodySource.fromFactory {
      AsyncStream<Data> { continuation in
        let half = payload.count / 2
        continuation.yield(payload.prefix(half))
        Task {
          await gate.wait()
          continuation.yield(payload.suffix(from: half))
          continuation.finish()
        }
      }
    }
    let response = try await DefaultApiClient().sendRequest(
      method: "PUT", url: server.url("/items/blob"), headers: [:], body: source)
    #expect(response.statusCode == 200)
    let head = server.heads[0].lowercased()
    #expect(head.contains("transfer-encoding: chunked"), "an unknown length is chunked")
    #expect(!head.contains("content-length"), "and carries no Content-Length")
    #expect(seen.get()?.chunked == true)
    #expect(seen.get()?.bytes == payload, "every byte arrived in order")
  }

  /* A streamed upload with a known length sends Content-Length and no chunking. */
  @Test func testBhvStreaming024AStreamedUploadWithAKnownLengthSendsContentLength() async throws {
    let payload = patterned(100_000)
    let file = FileManager.default.temporaryDirectory.appendingPathComponent(
      "upload-\(UUID().uuidString).bin")
    try payload.write(to: file)
    defer { try? FileManager.default.removeItem(at: file) }
    let seen = LockedValue<[RawConnection.Upload]>([])
    let server = try RawServer { connection, _, head in
      seen.update { $0.append(connection.readUpload(head: head)) }
      connection.reply(200)
    }
    defer { server.stop() }
    let sources: [BodySource] = [
      BodySource.of(payload),
      BodySource.ofFile(file),
      BodySource.fromFactory(length: payload.count) {
        AsyncStream<Data> { continuation in
          continuation.yield(payload)
          continuation.finish()
        }
      },
      BodySource.once(InputStream(data: payload), length: payload.count),
    ]
    let client = DefaultApiClient()
    for source in sources {
      let response = try await client.sendRequest(
        method: "PUT", url: server.url("/items/blob"), headers: [:], body: source)
      #expect(response.statusCode == 200)
    }
    let uploads = seen.get()
    #expect(uploads.count == sources.count)
    for (index, upload) in uploads.enumerated() {
      let head = server.heads[index].lowercased()
      #expect(head.contains("content-length: \(payload.count)"), "source \(index)")
      #expect(!head.contains("transfer-encoding"), "source \(index) is not chunked")
      #expect(!upload.chunked)
      #expect(upload.bytes == payload, "source \(index)")
    }
    #expect(sources[0].description == "BodySource(kind: bytes, length: 100000 bytes)")
    #expect(sources[3].description == "BodySource(kind: single use, length: 100000 bytes)")
    #expect(
      BodySource.fromFactory { AsyncStream<Data> { $0.finish() } }.description
        == "BodySource(kind: factory, length: unknown)")
  }

