  /* A replayable upload is read again and retried after a 503; a single-use one is sent once and its error stands. */
  @Test
  func
    testBhvStreaming026AReplayableUploadIsRewoundAndRetriedAfterA503AndASingleUseUploadIsNotRetriedAndSurfacesTheOriginalError()
    async throws
  {
    let payload = patterned(20_000)
    let seen = LockedValue<[RawConnection.Upload]>([])
    let server = try RawServer { connection, hit, head in
      seen.update { $0.append(connection.readUpload(head: head)) }
      connection.reply(hit == 1 ? 503 : 200, "Retry-After: 0")
    }
    defer { server.stop() }
    let opens = LockedValue<Int>(0)
    let replayable = BodySource.fromFactory(length: payload.count) {
      opens.update { $0 += 1 }
      return AsyncStream<Data> { continuation in
        continuation.yield(payload)
        continuation.finish()
      }
    }
    let response = try await DefaultApiClient().sendRequest(
      method: "PUT", url: server.url("/items/blob"), headers: [:], body: replayable)
    #expect(response.statusCode == 200)
    #expect(server.hits == 2, "the 503 was retried")
    #expect(opens.get() == 2, "the source was opened again for the retry")
    #expect(seen.get().map(\.bytes) == [payload, payload], "the retry carries the whole body")

    let failing = try RawServer { connection, _, head in
      _ = connection.readUpload(head: head)
      connection.reply(503, "Retry-After: 0")
    }
    defer { failing.stop() }
    let single = try await DefaultApiClient().sendRequest(
      method: "PUT", url: failing.url("/items/blob"), headers: [:],
      body: BodySource.once(InputStream(data: payload)))
    #expect(single.statusCode == 503, "the original answer is returned unchanged")
    #expect(failing.hits == 1, "a single use body is sent once")
  }

  /* A 307 or 308 with a single-use upload is refused and nothing is sent on; a replayable upload follows it. */
  @Test func testBhvStreaming027A307Or308WithASingleUseUploadIsRefusedAndTheBodyIsNeverBuffered()
    async throws
  {
    let payload = patterned(20_000)
    for status in [307, 308] {
      let landed = LockedValue<[RawConnection.Upload]>([])
      let target = try RawServer { connection, _, head in
        landed.update { $0.append(connection.readUpload(head: head)) }
        connection.reply(200)
      }
      defer { target.stop() }
      let origin = try RawServer { connection, _, head in
        _ = connection.readUpload(head: head)
        connection.reply(status, "Location: \(target.url("/items/final"))")
      }
      defer { origin.stop() }

      let once = InputStream(data: payload)
      let error = await #expect(throws: ApiError.self) {
        _ = try await DefaultApiClient().sendRequest(
          method: "PUT", url: origin.url("/items/blob"), headers: [:],
          body: BodySource.once(once))
      }
      #expect(error?.message.contains("Refusing to replay a streamed request body") == true)
      #expect(error?.statusCode == status)
      #expect(target.hits == 0, "\(status): nothing was sent to the new location")
      #expect(origin.hits == 1)
      #expect(!once.hasBytesAvailable, "the stream was read once, as it was sent")
      #expect(once.streamStatus != .closed)

      let followed = try await DefaultApiClient().sendRequest(
        method: "PUT", url: origin.url("/items/blob"), headers: [:],
        body: BodySource.fromFactory {
          AsyncStream<Data> { continuation in
            continuation.yield(payload)
            continuation.finish()
          }
        })
      #expect(followed.statusCode == 200, "\(status): a replayable body follows it")
      #expect(landed.get().map(\.bytes) == [payload])
    }
  }

