  @Test func testBhvRetries020PostBodyIsRefusedAcrossHttpsToHttp() throws {
    var post = URLRequest(url: try #require(URL(string: "http://other.example/x")))
    post.httpMethod = "POST"
    post.httpBody = Data("{}".utf8)
